            prev_index = max_sum.bisect_left(nums[i]) - 1

            if prev_index >= 0:
                prev_value = max_sum.peekitem(prev_index)[0]
                max_sum[nums[i]] = max(max_sum[nums[i]], max_sum[prev_value] + nums[i])

