    def minEdgeReversals(self, n: int, edges: List[List[int]]) -> List[int]:
        g = defaultdict(list)
        ans = [0] * n

        for u, v in edges:
            g[u].append((v, 1))  
            g[v].append((u, 0))  

        def bfs(start):
            queue = deque([(start, 0)])  
            visited = set()
            visited.add(start)
            local_ans = [0] * n

            while queue:
                par, parCnt = queue.popleft()
                local_ans[par] = parCnt

                for child, cnt in g[par]:
                    if child not in visited:
                        visited.add(child)
                        queue.append((child, parCnt + cnt))

            return local_ans

        total_reversals = [0] * n
        visited_global = set()

        for i in range(n):
            if i not in visited_global:
                local_ans = bfs(i)
                for j in range(n):
                    if local_ans[j] > 0:
                        visited_global.add(j)
                for j in range(n):
                    total_reversals[j] += local_ans[j]

