    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7

        if len(s) != len(t) or len(s) == 0:
            return 0

        ss = s + s
        n = len(s)

        if t not in ss:
            return 0

        r = 0
        for i in range(n):
            if ss[i:i+n] == t:
                r += 1

        if r == 0:
            return 0

        left = r if k % 2 == 0 else 0

        a1 = (n - 1) * r

        q = (n - 1) ** 2

        if k == 0:
            return left % MOD

        if q == 1:
            ans = (a1 * (k // 2) + left) % MOD
        else:
            ans = (a1 * (pow(q, k // 2, MOD) - 1) * pow(q - 1, MOD - 2, MOD) + left) % MOD

        return ans

