from collections import Counter

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        count = Counter(nums)

        if sum(num * count[num] for num in count) < target:
            return -1

        ops = 0
        total = 0

        sorted_nums = sorted(count.keys(), reverse=True)

        for num in sorted_nums:
            while count[num] > 0 and total < target:
                total += num
                count[num] -= 1

            if total >= target:
                break

            while num > 1 and total < target:
                new_num = num // 2
                ops += 1
                count[new_num] += 2
                count[num] -= 1
                total += new_num

                if total >= target:
                    break

        return ops if total >= target else -1

from collections import defaultdict, deque
from typing import List

class Solution:
    def findMaximumElegance(self, items: List[List[int]], k: int) -> int:
        if k > len(items):
            return 0

        items.sort(reverse=True, key=lambda x: x[0])

        sm = 0
        seenCats = set()
        dups = deque()

        for i in range(k):
            headPrf, headCat = items[i]
            sm += headPrf
            if headCat in seenCats:
                dups.append(headPrf)
            else:
                seenCats.add(headCat)

        numCats = len(seenCats)
        ans = sm + numCats ** 2

        for i in range(k, len(items)):
            tailPrf, tailCat = items[i]
            if tailCat in seenCats:
                continue

            if dups:
                leastProfitable = dups.popleft()
                sm += tailPrf - leastProfitable
            else:
                sm += tailPrf

            seenCats.add(tailCat)
            numCats = len(seenCats)
            if numCats >= k:
                ans = max(ans, sm + numCats ** 2)

        return ans

