import heapq

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        total_sum = sum(nums1)

        if total_sum <= x:
            return 0

        max_heap = []
        for i in range(n):
            if nums2[i] > 0:
                max_wait_time = (total_sum - x + nums2[i] - 1) // nums2[i]
                heapq.heappush(max_heap, (-max_wait_time, nums1[i], nums2[i]))

        time = 0
        while max_heap:
            time += 1
            max_wait_time, current_value, increment = heapq.heappop(max_heap)
            max_wait_time = -max_wait_time

            new_value = current_value + increment * time

            total_sum -= (new_value - current_value)

            if total_sum <= x:
                return time

            if increment > 0:
                new_max_wait_time = (total_sum - x + increment - 1) // increment
                heapq.heappush(max_heap, (-(new_max_wait_time), new_value, increment))

        return -1

from collections import defaultdict, Counter
from typing import List

class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        lookup = defaultdict(list)
        total = 0

        for index, p in enumerate(parent):
            if p != -1:
                lookup[p].append(index)

        counter = Counter()

        def go(node: int, mask: int):
            nonlocal total
            total += counter[mask]

            for i in range(26):
                total += counter[mask ^ (1 << i)]

            counter[mask] += 1

            for nxt in lookup[node]:
                go(nxt, mask ^ (1 << (ord(s[nxt]) - ord('a'))))

            counter[mask] -= 1

        go(0, 0)  # Start with mask 0 for the root node
        return total
